<?php
session_start();if(!isset($_SESSION['user_id'])||$_SESSION['role']!=='patient'){header('Location: ../auth/login.php');exit();}include('../config/database.php');$user_id=(int)$_SESSION['user_id'];$name=$_SESSION['name'];if(isset($_POST['mark_all_read'])){mysqli_query($conn,"UPDATE notifications SET is_read=1 WHERE user_id=$user_id");header('Location: notifications.php');exit();}$q=mysqli_query($conn,"SELECT id,message,type,is_read,created_at FROM notifications WHERE user_id=$user_id ORDER BY created_at DESC");?><!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Notifications | ClinicCare</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><link rel="stylesheet" href="../css/style.css"><link rel="stylesheet" href="../css/patient.css"></head><body><div class="patient-layout"><aside class="patient-sidebar"><div class="patient-brand"><div class="patient-brand-icon"><i class="fa-solid fa-plus"></i></div><div><h3>ClinicCare</h3><span>Patient Portal</span></div></div><div class="patient-profile"><div class="patient-avatar-small"><?php echo strtoupper(substr($name,0,1));?></div><div class="patient-profile-info"><strong><?php echo htmlspecialchars($name);?></strong><span>Patient</span></div></div><nav class="patient-nav"><div class="patient-nav-heading">MAIN MENU</div><a href="dashboard.php" class="patient-nav-link">Dashboard</a><a href="book_appointment.php" class="patient-nav-link">Book Appointment</a><a href="appointments.php" class="patient-nav-link">Appointments</a><a href="queue.php" class="patient-nav-link">Live Queue</a><a href="prescriptions.php" class="patient-nav-link">Prescriptions</a><a href="notifications.php" class="patient-nav-link active">Notifications</a></nav><div class="patient-sidebar-bottom"><a href="../auth/logout.php" class="patient-logout"><i class="fa-solid fa-right-from-bracket"></i>Logout</a></div></aside><main class="patient-main"><header class="patient-topbar"><div><h1>Notifications</h1><p>Appointment and prescription updates.</p></div></header><div class="patient-content"><section class="patient-card"><div class="patient-card-header"><div><h2>Notifications</h2><p>Latest messages from ClinicCare.</p></div><form method="POST"><button name="mark_all_read" class="patient-secondary-btn"><i class="fa-solid fa-check-double"></i>Mark all as read</button></form></div><div><?php if(mysqli_num_rows($q)){while($n=mysqli_fetch_assoc($q)){?><div class="notification-row <?php echo $n['is_read']?'':'unread';?>"><div class="notification-icon"><i class="fa-solid fa-bell"></i></div><div><strong><?php echo htmlspecialchars($n['message']);?></strong><small><?php echo date('d M Y, h:i A',strtotime($n['created_at']));?></small></div></div><?php }}else{?><div class="cc-empty"><div class="cc-empty-icon"><i class="fa-regular fa-bell"></i></div><h3>No notifications</h3><p>New notifications will appear here.</p></div><?php }?></div></section></div></main></div></body></html>
